// params_ini.hpp - reader for parser.ini (generated by rtvision-run, docs/PARSERS.md):
//
//   [parser]
//   family=yolo_e2e            # yolo_e2e | yolo_raw | detr | efficient_nms (required)
//   layers=output0             # comma-separated output layer names, in family order
//   box_format=xyxy_px         # family default if omitted
//   activation=none            # family default if omitted
//   has_background_class=false
//   num_classes=80             # 0 or omitted = use nvinfer's num-detected-classes
//   allowed_class_ids=0        # comma-separated; omitted/empty = all classes
//   topk=300
//
// Strict: unknown sections/keys and invalid values are errors (the file is machine-generated,
// so an unknown key means a generator/binary mismatch). '#' and ';' start comments.
#pragma once

#include <string>
#include <vector>

#include "detection.hpp"

namespace rtvision {

struct ParserConfig {
    std::string family;
    std::vector<std::string> layers;
    BoxFormat box_format = BoxFormat::XYXY_PX;
    Activation activation = Activation::NONE;
    bool has_background_class = false;
    int num_classes = 0;
    std::vector<int> allowed_class_ids;
    int topk = 300;
};

// Default box format / activation of a family. Returns false for an unknown family.
bool family_defaults(const std::string &family, BoxFormat &box, Activation &act);

bool parse_parser_ini(const std::string &text, ParserConfig &out, std::string &error);
bool load_parser_ini(const std::string &path, ParserConfig &out, std::string &error);

} // namespace rtvision
